cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');
const crypto = require('crypto');
const reminderId = crypto.randomUUID();
const now = Math.floor(Date.now() / 1000);
db.prepare('INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at) VALUES (?, ?, ?, ?, ?, ?, datetime(\"now\"))').run(
  reminderId,
  \"Follow up with Maya if she's not there by 6:30 PM.\",
  now,
  1788269400,
  37.7749,
  -122.4194
);
console.log('New reminder created with ID:', reminderId);
// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log(JSON.stringify(row, null, 2));
"

